src=re.sub(r"function objective\(\)\{.*?\}\nfunction updateCheckpoint\(\)\{.*?\}","""let currentZone='';function objective(){if(complete)return;let best=null,bd=1e9;for(const q of sites.zones||[]){const d=Math.hypot(player.x-q.x,player.z-q.z);if(d<q.r&&d<bd){best=q;bd=d}}if(best&&best.id!==currentZone){currentZone=best.id;objectiveEl.textContent=best.name;objectiveEl.classList.add('show');clearTimeout(objective._t);objective._t=setTimeout(()=>objectiveEl.classList.remove('show'),2600)}}\nfunction updateCheckpoint(){let best=checkpoint,bd=1e9;for(let i=0;i<checkpoints.length;i++){const p=checkpoints[i],d=Math.hypot(player.x-p.x,player.z-p.z);if(d<12&&d<bd){best=i;bd=d}}if(best>checkpoint){checkpoint=best;toast('CHECKPOINT',650)}}""",src,flags=re.S)
